  "Need Immediate Help Booking?": { so: "Ma U Baahan Tahay Caawimo Degdeg ah oo Ballan ah?", ar: "هل تحتاج مساعدة فورية للحجز؟" },
  "Our coordinators are available on call to help you register or answer questions. Call our toll-free short number directly.": { so: "Shaqaalahayagu telefoon ayay diyaar ugu yihiin inay kaa caawiyaan diiwaangelinta ama su'aalaha. Si toos ah uga wac lambarkeenna gaaban ee bilaashka ah.", ar: "منسقونا متاحون عبر الهاتف لمساعدتك في التسجيل أو الإجابة عن الأسئلة. اتصل مباشرة برقمنا القصير المجاني." },
  "Call 4446 Now": { so: "Hadda Wac 4446", ar: "اتصل الآن على 4446" },
  "Important Instructions": { so: "Tilmaamo Muhiim ah", ar: "تعليمات مهمة" },
  "Bring Your Documents": { so: "Soo Qaado Dukumentiyadaada", ar: "أحضر مستنداتك" },
  "Please remember to bring your national ID card, previous prescriptions, and health insurance card (if applicable).": { so: "Fadlan soo qaado kaarka aqoonsiga, warqadihii daawooyinka hore iyo kaarka caymiska caafimaadka haddii uu jiro.", ar: "يرجى إحضار بطاقة الهوية والوصفات السابقة وبطاقة التأمين الصحي إن وجدت." },
  "Arrive Early": { so: "Hore U Imow", ar: "احضر مبكراً" },
  "We recommend arriving 15 minutes before your scheduled appointment slot to complete any check-in paperwork.": { so: "Waxaan kugula talinaynaa inaad timaaddo 15 daqiiqo ka hor ballanta si aad u dhammaystirto waraaqaha diiwaangelinta.", ar: "ننصح بالحضور قبل الموعد بـ15 دقيقة لإكمال إجراءات التسجيل." },
  "Rescheduling & Cancellation": { so: "Beddelidda & Joojinta", ar: "إعادة الجدولة والإلغاء" },
  "If you need to change or cancel your slot, please call us on 4446 at least 24 hours in advance.": { so: "Haddii aad u baahan tahay inaad beddesho ama joojiso ballanta, fadlan naga soo wac 4446 ugu yaraan 24 saac kahor.", ar: "إذا أردت تغيير الموعد أو إلغاءه، يرجى الاتصال على 4446 قبل 24 ساعة على الأقل." },
  "Departments Page": { so: "Bogga Waaxyaha", ar: "صفحة الأقسام" },
  "Our Departments": { so: "Waaxyahayaga", ar: "أقسامنا" },
  "Quick Information": { so: "Xog Degdeg ah", ar: "معلومات سريعة" },
  "24 Hours / 7 Days": { so: "24 Saac / 7 Maalmood", ar: "24 ساعة / 7 أيام" },
