  "Call 4446": { so: "Wac 4446", ar: "اتصل 4446" },
  "Key Services & Highlights": { so: "Adeegyada Muhiimka ah", ar: "الخدمات والمميزات الرئيسية" },
  "Need Consultation or Have Questions?": { so: "Ma U Baahan Tahay La-talin ama Ma Qabtaa Su'aalo?", ar: "هل تحتاج استشارة أو لديك أسئلة؟" },
  "Get in touch with our experts or schedule an appointment with our department specialists today.": { so: "La xiriir khubaradayada ama maanta ballan la qabso takhasusleyaasha waaxda.", ar: "تواصل مع خبرائنا أو احجز اليوم موعداً مع أخصائيي القسم." },
  "Inpatient Services": { so: "Adeegyada Jiifka", ar: "خدمات التنويم" },
  Inpatient: { so: "Jiifka", ar: "التنويم" },
  "Outpatient Clinic": { so: "Rugta Bukaan-socodka", ar: "العيادات الخارجية" },
  Outpatient: { so: "Bukaan-socod", ar: "العيادات الخارجية" },
  Clinic: { so: "Rugta", ar: "العيادة" },
  "Operating Theatre": { so: "Qolka Qalliinka", ar: "غرفة العمليات" },
