  "Health Checkups": { so: "Baaritaannada Caafimaadka", ar: "الفحوصات الصحية" },
  "Hospital Services": { so: "Adeegyada Isbitaalka", ar: "خدمات المستشفى" },
  "Discover our health screening and routine checkup services.": { so: "Baro adeegyada baaritaanka iyo hubinta caafimaadka joogtada ah.", ar: "اكتشف خدمات الكشف الصحي والفحوصات الدورية." },
  "Explore the hospital services available to patients and their families.": { so: "Eeg adeegyada isbitaalka ee bukaanka iyo qoysaskooda loo heli karo.", ar: "استكشف خدمات المستشفى المتاحة للمرضى وعائلاتهم." },
  "Preventive Care": { so: "Daryeelka Ka-hortagga", ar: "الرعاية الوقائية" },
  "Choose Your Checkup Package": { so: "Dooro Xirmada Baaritaankaaga", ar: "اختر باقة الفحص" },
  "Investing in early checkups helps prevent health complications. Select a package below to inspect the details and book a screening.": { so: "Baaritaanka hore wuxuu ka hortagaa dhibaatooyin caafimaad. Hoos ka dooro xirmo si aad faahfaahinta u aragto una qabsato baaritaan.", ar: "يساعد الاستثمار في الفحوصات المبكرة على منع المضاعفات الصحية. اختر باقة أدناه للاطلاع على التفاصيل وحجز الفحص." },
  "Whole Body Checkup Male": { so: "Baaritaanka Jirka oo Dhan ee Ragga", ar: "فحص شامل للرجال" },
  "Whole Body Checkup Female": { so: "Baaritaanka Jirka oo Dhan ee Haweenka", ar: "فحص شامل للنساء" },
  "Basic Male Checkup": { so: "Baaritaanka Aasaasiga ah ee Ragga", ar: "الفحص الأساسي للرجال" },
  "Basic Female Checkup": { so: "Baaritaanka Aasaasiga ah ee Haweenka", ar: "الفحص الأساسي للنساء" },
  "Health Checkups for Pregnancy": { so: "Baaritaannada Caafimaadka Uurka", ar: "فحوصات الحمل الصحية" },
  "This package comprises 49 Investigations + 5 Specialist Consultations.": { so: "Xirmadani waxay ka kooban tahay 49 baaritaan + 5 la-talin takhasus.", ar: "تتضمن هذه الباقة 49 فحصاً و5 استشارات تخصصية." },
  "This package comprises 44 Investigations + 5 Specialist Consultations.": { so: "Xirmadani waxay ka kooban tahay 44 baaritaan + 5 la-talin takhasus.", ar: "تتضمن هذه الباقة 44 فحصاً و5 استشارات تخصصية." },
  "This package comprises 23 Investigations + 3 Specialist Consultations.": { so: "Xirmadani waxay ka kooban tahay 23 baaritaan + 3 la-talin takhasus.", ar: "تتضمن هذه الباقة 23 فحصاً و3 استشارات تخصصية." },
  "This package comprises 32 Investigations.": { so: "Xirmadani waxay ka kooban tahay 32 baaritaan.", ar: "تتضمن هذه الباقة 32 فحصاً." },
  "Comprehensive health evaluation designed specifically for men to assess overall physiological health, detect early signs of chronic diseases, and optimize wellness.": { so: "Qiimayn caafimaad oo dhammaystiran oo ragga loogu talagalay si loo baaro caafimaadka guud, loona ogaado calaamadaha hore ee cudurrada daba-dheeraada.", ar: "تقييم صحي شامل مصمم للرجال لتقييم الصحة العامة واكتشاف العلامات المبكرة للأمراض المزمنة وتحسين العافية." },
  "Complete medical checkup designed for women to evaluate vital organs, reproductive health, hormonal balance, and screen for common female health risks.": { so: "Baaritaan caafimaad oo dhammaystiran oo haweenka loogu talagalay si loo qiimeeyo xubnaha muhiimka ah, caafimaadka taranka, dheelitirka hormoonnada iyo khataraha caafimaad ee caanka ah.", ar: "فحص طبي شامل للنساء لتقييم الأعضاء الحيوية والصحة الإنجابية والتوازن الهرموني والكشف عن المخاطر الصحية الشائعة." },
  "Essential preventive checkup to monitor key health parameters and catch common health issues in men before they escalate.": { so: "Baaritaan ka-hortag oo muhiim ah si loola socdo caafimaadka ragga loona ogaado dhibaatooyinka ka hor intaanay sii xumaan.", ar: "فحص وقائي أساسي لمراقبة مؤشرات الصحة واكتشاف المشكلات الشائعة لدى الرجال قبل تفاقمها." },
  "Essential screening for women of all age groups to review primary wellness indicators and ensure peace of mind.": { so: "Baaritaan muhiim ah oo haweenka da' kasta ah loogu eegayo tilmaamayaasha caafimaadka aasaasiga ah.", ar: "فحص أساسي للنساء من جميع الأعمار لمراجعة مؤشرات العافية الأساسية والاطمئنان." },
  "Carefully designed health checks to ensure the absolute well-being of both mother and baby throughout the gestational period.": { so: "Baaritaanno si taxaddar leh loogu talagalay badqabka hooyada iyo ilmaha muddada uurka oo dhan.", ar: "فحوصات مصممة بعناية لضمان صحة الأم والطفل طوال فترة الحمل." },
